// Generates testdata/ats-hash-index-oracle.txt: upstream DSS's own ats-hash-index attributes
// and archive-time-stamp-v3 message imprints for the CAdES documents copied into
// testdata/upstream/. It is the Java oracle of cades_level_baseline_lta_timestamp_extractor_kat_test.go
// - every expected byte string in that test comes from running this program, never from hand
// derivation.
//
// Both the creation side (CadesLevelBaselineLTATimestampExtractor#getAtsHashIndex, for each of
// the three ats-hash-index versions and two hash-index digest algorithms) and the verification
// side (#getVerifiedAtsHashIndex, over every archive time-stamp the document carries) are
// dumped, together with the archive-time-stamp-v3 message imprint
// (#getArchiveTimestampV3MessageImprint) wherever the signed content is available.
//
// Run it with OpenJDK 21 against an upstream DSS 6.5.RC1 build installed in the local Maven
// repository (mvn -pl dss-cades,dss-cms-object -am install -DskipTests):
//
//   cd $DSS_UPSTREAM_HOME  (your built upstream DSS 6.5.RC1 checkout)
//   mvn -q -o -pl dss-cades dependency:build-classpath -Dmdep.outputFile=/tmp/cp.txt -Dmdep.includeScope=test
//   CP=$(cat /tmp/cp.txt):$HOME/.m2/repository/eu/europa/ec/joinup/sd-dss/dss-cms-object/6.5.RC1/dss-cms-object-6.5.RC1.jar
//   CP=$CP:$HOME/.m2/repository/eu/europa/ec/joinup/sd-dss/dss-cades/6.5.RC1/dss-cades-6.5.RC1.jar
//   javac -cp "$CP" -d /tmp/ltaoracle AtsHashIndexOracle.java
//   java -cp "$CP:/tmp/ltaoracle" AtsHashIndexOracle <testdata directory>
//
// dss-cms-object has to be added by hand: it is the runtime CMS implementation dss-cms selects
// through its service loader, and dss-cades declares neither of the two implementations.
import eu.europa.esig.dss.cades.signature.CadesLevelBaselineLTATimestampExtractor;
import eu.europa.esig.dss.cades.validation.CAdESSignature;
import eu.europa.esig.dss.cades.validation.CMSDocumentAnalyzer;
import eu.europa.esig.dss.enumerations.DigestAlgorithm;
import eu.europa.esig.dss.model.DSSDocument;
import eu.europa.esig.dss.model.DSSMessageDigest;
import eu.europa.esig.dss.model.FileDocument;
import eu.europa.esig.dss.spi.DSSASN1Utils;
import eu.europa.esig.dss.spi.DSSUtils;
import eu.europa.esig.dss.spi.signature.AdvancedSignature;
import eu.europa.esig.dss.spi.validation.CommonCertificateVerifier;
import eu.europa.esig.dss.spi.x509.tsp.ArchiveTimestampHashIndexStatus;
import eu.europa.esig.dss.spi.x509.tsp.TimestampToken;
import org.bouncycastle.asn1.ASN1ObjectIdentifier;
import org.bouncycastle.asn1.cms.Attribute;
import org.bouncycastle.asn1.cms.AttributeTable;
import org.bouncycastle.cms.SignerInformation;

import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

public class AtsHashIndexOracle {

    /** The documents the KAT runs over, all copied into testdata/upstream/ from
     *  dss-cades/src/test/resources/validation/. */
    static final String[] FILES = {
        "CAdESDoubleLTA.p7m",            // 3 SignedData certificates, 1 CRL, 1 basic OCSP response, 2 ATSv3
        "cades-lta-en319122.cms",        // ats-hash-index-v3 (EN 319 122-1)
        "cades-lta-ts101733.cms",        // ats-hash-index (TS 101 733)
        "Signature-C-HU_POL-3.p7m",      // 2 OCSP responses under id-ri-ocsp-response
        "cades-ats-v3-wrong-cert.p7m",   // ats-hash-index referencing an absent certificate
        "cades-ats-v3-rev-val-crl.p7s",  // detached, revocation data inside the archive time-stamp
    };

    /** The three ats-hash-index versions: id-aa-ATSHashIndex, -v2 and -v3. */
    static final ASN1ObjectIdentifier[] VERSIONS = {
        new ASN1ObjectIdentifier("0.4.0.1733.2.5"),
        new ASN1ObjectIdentifier("0.4.0.19122.1.4"),
        new ASN1ObjectIdentifier("0.4.0.19122.1.5"),
    };

    /** SHA-256 is the default hash-index algorithm (and is therefore omitted from an
     *  ats-hash-index v1); SHA-512 forces the AlgorithmIdentifier to be written out. */
    static final DigestAlgorithm[] DIGESTS = { DigestAlgorithm.SHA256, DigestAlgorithm.SHA512 };

    public static void main(String[] args) throws Exception {
        Path testdata = Paths.get(args[0]);
        try (PrintWriter out = new PrintWriter(Files.newBufferedWriter(
                testdata.resolve("ats-hash-index-oracle.txt"), StandardCharsets.UTF_8))) {
            out.println("# ats-hash-index and archive-time-stamp-v3 message imprints, as computed by");
            out.println("# eu.europa.esig.dss.cades.signature.CadesLevelBaselineLTATimestampExtractor of DSS 6.5.RC1.");
            out.println("# Generated by gen/AtsHashIndexOracle.java - see its header. Do not edit by hand.");
            for (String file : FILES) {
                dumpFile(out, testdata.resolve("upstream").resolve(file), file);
            }
        }
        try (PrintWriter out = new PrintWriter(Files.newBufferedWriter(
                testdata.resolve("attribute-table-order-oracle.txt"), StandardCharsets.UTF_8))) {
            out.println("# org.bouncycastle.asn1.cms.AttributeTable#toASN1EncodableVector() ordering (BouncyCastle 1.84),");
            out.println("# which the unsignedAttrsHashIndex of an ats-hash-index is built by iterating.");
            out.println("# Each case is 'IN <attrType>... / OUT <attrType>...'.");
            out.println("# Generated by gen/AtsHashIndexOracle.java - see its header. Do not edit by hand.");
            for (String[] attrTypes : ATTRIBUTE_TABLE_CASES) {
                dumpAttributeTableOrder(out, attrTypes);
            }
        }
    }

    /** Attribute type sequences whose AttributeTable ordering is pinned. The last two cross the
     *  Hashtable's rehash thresholds (8 entries, then 16), which no upstream test document does. */
    static final String[][] ATTRIBUTE_TABLE_CASES = {
        { "1.2.840.113549.1.9.16.2.14" },
        { "1.2.840.113549.1.9.16.2.14", "0.4.0.1733.2.4", "0.4.0.1733.2.4" },
        { "0.4.0.1733.2.4", "1.2.840.113549.1.9.16.2.14" },
        { "1.2.840.113549.1.9.16.2.21", "1.2.840.113549.1.9.16.2.22", "1.2.840.113549.1.9.16.2.23",
          "0.4.0.1733.2.4", "1.2.840.113549.1.9.16.2.48", "1.2.840.113549.1.9.16.2.14",
          "1.2.840.113549.1.9.16.2.24" },
        // 12 distinct types: one rehash, from 11 to 23 slots.
        { "1.2.840.113549.1.9.16.2.14", "1.2.840.113549.1.9.16.2.21", "1.2.840.113549.1.9.16.2.22",
          "1.2.840.113549.1.9.16.2.23", "1.2.840.113549.1.9.16.2.24", "1.2.840.113549.1.9.16.2.25",
          "1.2.840.113549.1.9.16.2.26", "1.2.840.113549.1.9.16.2.27", "1.2.840.113549.1.9.16.2.48",
          "0.4.0.1733.2.4", "0.4.0.1733.2.5", "0.4.0.19122.1.5" },
        // 20 distinct types with repetitions: two rehashes, 11 -> 23 -> 47 slots.
        { "1.2.840.113549.1.9.16.2.1", "1.2.840.113549.1.9.16.2.2", "1.2.840.113549.1.9.16.2.3",
          "1.2.840.113549.1.9.16.2.4", "1.2.840.113549.1.9.16.2.5", "1.2.840.113549.1.9.16.2.6",
          "1.2.840.113549.1.9.16.2.7", "1.2.840.113549.1.9.16.2.8", "1.2.840.113549.1.9.16.2.9",
          "1.2.840.113549.1.9.16.2.10", "1.2.840.113549.1.9.16.2.11", "1.2.840.113549.1.9.16.2.12",
          "1.2.840.113549.1.9.16.2.1", "1.2.840.113549.1.9.16.2.13", "1.2.840.113549.1.9.16.2.14",
          "1.2.840.113549.1.9.16.2.15", "1.2.840.113549.1.9.16.2.16", "1.2.840.113549.1.9.16.2.17",
          "1.2.840.113549.1.9.16.2.18", "0.4.0.1733.2.4", "0.4.0.19122.1.4", "1.2.840.113549.1.9.16.2.1" },
    };

    static void dumpAttributeTableOrder(PrintWriter out, String[] attrTypes) {
        org.bouncycastle.asn1.ASN1EncodableVector set = new org.bouncycastle.asn1.ASN1EncodableVector();
        for (int i = 0; i < attrTypes.length; i++) {
            // A distinct value per attribute keeps the members of a repeated attrType apart.
            set.add(new Attribute(new ASN1ObjectIdentifier(attrTypes[i]),
                    new org.bouncycastle.asn1.DERSet(new org.bouncycastle.asn1.ASN1Integer(i))));
        }
        AttributeTable table = new AttributeTable(new org.bouncycastle.asn1.DLSet(set));
        out.println();
        out.println("IN " + String.join(" ", attrTypes));
        StringBuilder ordered = new StringBuilder("OUT");
        org.bouncycastle.asn1.ASN1EncodableVector vector = table.toASN1EncodableVector();
        for (int i = 0; i < vector.size(); i++) {
            Attribute attribute = Attribute.getInstance(vector.get(i));
            ordered.append(' ').append(attribute.getAttrType().getId()).append('#')
                    .append(((org.bouncycastle.asn1.ASN1Integer) attribute.getAttrValues().getObjectAt(0)).getValue());
        }
        out.println(ordered);
    }

    static void dumpFile(PrintWriter out, Path path, String name) throws Exception {
        out.println();
        out.println("FILE " + name);

        DSSDocument document = new FileDocument(path.toFile());
        CMSDocumentAnalyzer analyzer = new CMSDocumentAnalyzer(document);
        analyzer.setCertificateVerifier(new CommonCertificateVerifier());
        List<AdvancedSignature> signatures = analyzer.getSignatures();

        for (int i = 0; i < signatures.size(); i++) {
            CAdESSignature signature = (CAdESSignature) signatures.get(i);
            SignerInformation signerInformation = signature.getSignerInformation();

            out.println("SIG " + i);
            // The Go test locates the SignerInfo by this digest rather than by position.
            out.println("SIGNERINFO " + hex(DSSUtils.digest(DigestAlgorithm.SHA256,
                    signerInformation.toASN1Structure().getEncoded("DER"))));
            out.println("ECONTENTTYPE " + hex(DSSASN1Utils.getDEREncoded(signature.getCMS().getSignedContentType())));

            CadesLevelBaselineLTATimestampExtractor extractor =
                    new CadesLevelBaselineLTATimestampExtractor(signature);

            DSSDocument originalDocument = null;
            try {
                originalDocument = signature.getOriginalDocument();
            } catch (Exception e) {
                // Detached signature without the signed content: the message imprint cannot be
                // computed, only the ats-hash-index is dumped.
                out.println("ORIGINALDOCUMENT none");
            }
            if (originalDocument != null) {
                out.println("ORIGINALDOCUMENT " + hex(DSSUtils.toByteArray(originalDocument)));
            }

            for (ASN1ObjectIdentifier version : VERSIONS) {
                for (DigestAlgorithm digestAlgorithm : DIGESTS) {
                    Attribute atsHashIndex = extractor.getAtsHashIndex(signerInformation, digestAlgorithm, version);
                    out.println("ATS " + version.getId() + " " + digestAlgorithm.name() + " "
                            + hex(DSSASN1Utils.getDEREncoded(atsHashIndex)));
                    if (originalDocument != null) {
                        DSSMessageDigest imprint = extractor.getArchiveTimestampV3MessageImprint(
                                signerInformation, atsHashIndex, originalDocument, digestAlgorithm);
                        out.println("IMPRINT " + version.getId() + " " + digestAlgorithm.name() + " "
                                + hex(imprint.getValue()));
                    }
                }
            }

            List<TimestampToken> archiveTimestamps = signature.getArchiveTimestamps();
            for (int j = 0; j < archiveTimestamps.size(); j++) {
                TimestampToken timestampToken = archiveTimestamps.get(j);
                // The token is identified by the digest of its encoding rather than by its
                // position, which depends on how AdvancedSignature#getArchiveTimestamps() orders
                // the list.
                String id = hex(DSSUtils.digest(DigestAlgorithm.SHA256, timestampToken.getEncoded()));
                try {
                    Attribute verified = extractor.getVerifiedAtsHashIndex(signerInformation, timestampToken);
                    out.println("VERIFIED " + id + " " + hex(DSSASN1Utils.getDEREncoded(verified)));
                } catch (RuntimeException e) {
                    // An archive time-stamp carrying no ats-hash-index at all leaves the version
                    // identifier null, and upstream then builds `new Attribute(null, ...)`, whose
                    // encoding raises. The status below is set before that happens.
                    out.println("VERIFIEDTHROWS " + id + " " + e.getClass().getName());
                }
                ArchiveTimestampHashIndexStatus status = timestampToken.getAtsHashIndexStatus();
                out.println("VERIFIEDSTATUS " + id + " "
                        + (status.getVersion() != null ? status.getVersion().name() : "none") + " "
                        + String.join(" | ", status.getErrorMessages()));
            }
        }
    }

    static String hex(byte[] bytes) {
        if (bytes == null) {
            return "null";
        }
        StringBuilder builder = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            builder.append(Character.forDigit((b >> 4) & 0xf, 16));
            builder.append(Character.forDigit(b & 0xf, 16));
        }
        return builder.toString();
    }

}
